:root {
  --bg: #1e1e2f;
  --card-bg: #2a2a40;
  --accent: #f0a500;
  --text: #e0e0f0;
  --muted: #a0a0b8;
  --lamp-off: #3a3a55;
  --lamp-on: #f0a500;
  --radius: 12px;
  --font: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
}

* {
  box-sizing: border-box;
  margin: 0;
}

body {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bg);
  color: var(--text);
  font-family: var(--font);
  font-size: 16px;
  padding: 16px;
}

.card {
  background: var(--card-bg);
  border-radius: var(--radius);
  padding: 32px;
  width: 100%;
  max-width: 480px;
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.4);
}

h1 {
  font-size: 1.75rem;
  margin-bottom: 8px;
  letter-spacing: -0.5px;
}

.subtitle {
  color: var(--muted);
  margin-bottom: 24px;
}

.input-group {
  display: flex;
  flex-direction: column;
  gap: 8px;
  margin-bottom: 24px;
}

.input-group label {
  font-weight: 600;
  color: var(--muted);
  font-size: 0.875rem;
  text-transform: uppercase;
  letter-spacing: 0.5px;
}

#decimal-input {
  font-family: var(--font);
  font-size: 1.5rem;
  padding: 12px 16px;
  border: 2px solid var(--lamp-off);
  border-radius: var(--radius);
  background: var(--bg);
  color: var(--text);
  outline: none;
  transition: border-color 0.2s;
  width: 100%;
}

#decimal-input:hover {
  border-color: var(--muted);
}

#decimal-input:focus-visible {
  border-color: var(--accent);
  box-shadow: 0 0 0 3px rgba(240, 165, 0, 0.3);
}

.output-group {
  display: flex;
  gap: 16px;
  margin-bottom: 32px;
  flex-wrap: wrap;
}

.output-box {
  flex: 1;
  min-width: 120px;
  background: var(--bg);
  border-radius: var(--radius);
  padding: 16px;
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.output-label {
  font-size: 0.75rem;
  text-transform: uppercase;
  letter-spacing: 1px;
  color: var(--muted);
}

.output-value {
  font-size: 1.5rem;
  font-weight: 700;
  font-family: 'Courier New', monospace;
  color: var(--accent);
  word-break: break-all;
}

.lamps-section {
  margin-top: 8px;
}

.lamps-label {
  font-size: 0.875rem;
  color: var(--muted);
  margin-bottom: 12px;
}

.lamps-grid {
  display: grid;
  grid-template-columns: repeat(8, 1fr);
  gap: 8px;
}

.lamp {
  font-family: var(--font);
  font-size: 0.875rem;
  font-weight: 600;
  padding: 12px 4px;
  border: 2px solid var(--lamp-off);
  border-radius: 8px;
  background: var(--lamp-off);
  color: var(--muted);
  cursor: pointer;
  transition: background 0.15s, border-color 0.15s, color 0.15s, transform 0.1s;
  min-height: 56px;
  display: flex;
  align-items: center;
  justify-content: center;
}

.lamp:hover {
  border-color: var(--muted);
  background: #4a4a6a;
}

.lamp:focus-visible {
  outline: none;
  border-color: var(--accent);
  box-shadow: 0 0 0 3px rgba(240, 165, 0, 0.3);
}

.lamp:active {
  transform: scale(0.95);
}

.lamp[aria-pressed="true"] {
  background: var(--lamp-on);
  border-color: var(--lamp-on);
  color: #1e1e2f;
}

.lamp[aria-pressed="true"]:hover {
  background: #ffb820;
  border-color: #ffb820;
}

@media (max-width: 420px) {
  .card {
    padding: 20px;
  }
  h1 {
    font-size: 1.4rem;
  }
  .output-value {
    font-size: 1.2rem;
  }
  .lamps-grid {
    gap: 4px;
  }
  .lamp {
    font-size: 0.75rem;
    padding: 8px 2px;
    min-height: 48px;
  }
}

(function () {
  'use strict';

  const decimalInput = document.getElementById('decimal-input');
  const binaryOutput = document.getElementById('binary-output');
  const hexOutput = document.getElementById('hex-output');
  const lamps = Array.from(document.querySelectorAll('.lamp'));

  function toBinary(n) {
    return n.toString(2).padStart(8, '0');
  }

  function toHex(n) {
    return '0x' + n.toString(16).toUpperCase().padStart(2, '0');
  }

  function clamp(n) {
    return Math.min(255, Math.max(0, n));
  }

  function render(n) {
    const bin = toBinary(n);
    binaryOutput.textContent = bin;
    hexOutput.textContent = toHex(n);
    lamps.forEach(function (lamp) {
      const bit = parseInt(lamp.dataset.bit, 10);
      const isOn = (n >> bit) & 1;
      lamp.setAttribute('aria-pressed', isOn ? 'true' : 'false');
    });
  }

  function readInput() {
    const raw = decimalInput.value.trim();
    if (raw === '') {
      render(0);
      return;
    }
    let n = parseInt(raw, 10);
    if (isNaN(n)) {
      n = 0;
    }
    n = clamp(n);
    if (String(n) !== raw) {
      decimalInput.value = String(n);
    }
    render(n);
  }

  decimalInput.addEventListener('input', readInput);

  lamps.forEach(function (lamp) {
    lamp.addEventListener('click', function () {
      const bit = parseInt(lamp.dataset.bit, 10);
      const current = parseInt(decimalInput.value, 10) || 0;
      const next = current ^ (1 << bit);
      decimalInput.value = String(next);
      render(next);
    });
  });

  // Initial render
  render(0);
})();
